2	import { ClientDetail } from './ClientDetail';
3	import { formatMoney } from '../../ui/money';
4	
5	// This arm's convention: the page component owns the feature's state, data loading and layout.
6	type Client = { id: number; name: string; email: string; outstanding: number };
7	
8	// How the list is ordered: alphabetically by name, or by how much each client owes (most first).
9	type Sort = 'name' | 'outstanding';
10	
11	// A client must carry a proper email address. Keep it simple and local to the feature: a single
12	// non-whitespace local part, an @, and a dotted domain.
13	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
14	
15	export function ClientsPage() {
16	  const [clients, setClients] = useState<Client[]>([]);
17	  const [search, setSearch] = useState('');
18	  const [sort, setSort] = useState<Sort>('name');
19	  // Whether the list is showing the archived (tucked-away) clients instead of the main list.
20	  const [showArchived, setShowArchived] = useState(false);
21	  const [name, setName] = useState('');
22	  const [email, setEmail] = useState('');
23	  const [emailError, setEmailError] = useState<string | null>(null);
24	  const [openClientId, setOpenClientId] = useState<number | null>(null);
25	
26	  // Correcting a client: the row being edited, its draft name/email, and any email error.
27	  const [editClientId, setEditClientId] = useState<number | null>(null);
28	  const [editName, setEditName] = useState('');
29	  const [editEmail, setEditEmail] = useState('');
30	  const [editEmailError, setEditEmailError] = useState<string | null>(null);
31	
32	  async function load() {
33	    // The archived view lists the tucked-away clients so they can be brought back; the default view
34	    // lists the clients still in play, filtered and ordered the way the controls ask for.
35	    const url = showArchived
36	      ? '/api/clients?archived=true'
37	      : `/api/clients?q=${encodeURIComponent(search)}&sort=${encodeURIComponent(sort)}`;
38	    const res = await fetch(url);
39	    if (res.ok) {
40	      setClients(await res.json());
41	    }
42	  }
43	
44	  // Reload whenever the search term, chosen sort, or archived toggle changes — the server filters
45	  // and orders the list.
46	  useEffect(() => {
47	    void load();
48	  }, [search, sort, showArchived]);
49	
50	  // Bring an archived client back onto the main list, then reload the (now narrower) archived view.
51	  async function onRestore(id: number) {
52	    const res = await fetch(`/api/clients/${id}/restore`, { method: 'POST' });
53	    if (res.ok) {
54	      await load();
55	    }
56	  }
57	
58	  // Archiving tucks a client away: the row is kept but drops off the list and search. Close the
59	  // detail pane if it was open on the archived client, then reload the (now narrower) list.
60	  async function onArchive(id: number) {
61	    const res = await fetch(`/api/clients/${id}/archive`, { method: 'POST' });
62	    if (res.ok) {
63	      if (openClientId === id) {
64	        setOpenClientId(null);
65	      }
