22	export function ProjectsPage() {
23	  const [projects, setProjects] = useState<Project[]>([]);
24	  const [clients, setClients] = useState<Client[]>([]);
25	  const [tags, setTags] = useState<Tag[]>([]);
26	  const [name, setName] = useState('');
27	  const [clientId, setClientId] = useState('');
28	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
29	  const [code, setCode] = useState('');
30	  const [codeError, setCodeError] = useState<string | null>(null);
31	  const [tagFilter, setTagFilter] = useState('');
32	  const [statusFilter, setStatusFilter] = useState('');
33	  const [openProjectId, setOpenProjectId] = useState<number | null>(null);
34	  const [showArchived, setShowArchived] = useState(false);
35	  // Changing the status and tag filters in quick succession fires two overlapping fetches; without a
36	  // guard the earlier (less-narrowed) response can land last and clobber the narrower one. Tag each
37	  // request and apply only the latest, so combining both filters at once settles on the right list.
38	  const loadSeq = useRef(0);
39	
40	  async function loadProjects() {
41	    const seq = ++loadSeq.current;
42	    const params = new URLSearchParams();
43	    if (showArchived) {
44	      params.set('includeArchived', 'true');
45	    }
46	    if (tagFilter) {
47	      params.set('tagId', tagFilter);
48	    }
49	    if (statusFilter) {
50	      params.set('status', statusFilter);
51	    }
52	    const query = params.toString();
53	    const res = await fetch(query ? `/api/projects?${query}` : '/api/projects');
54	    if (res.ok && seq === loadSeq.current) {
55	      setProjects(await res.json());
56	    }
57	  }
58	
59	  async function loadClients() {
60	    const res = await fetch('/api/clients');
61	    if (res.ok) {
62	      setClients(await res.json());
63	    }
64	  }
65	
66	  async function loadTags() {
67	    const res = await fetch('/api/tags');
68	    if (res.ok) {
69	      setTags(await res.json());
70	    }
71	  }
72	
73	  useEffect(() => {
74	    void loadClients();
75	    void loadTags();
76	  }, []);
77	
78	  // Load the list on mount and re-fetch whenever the archived toggle flips or the tag filter
79	  // changes, so the list always reflects them. This is the single owner of the projects fetch:
80	  // keeping it the only caller avoids a stray initial request resolving after a filtered one and
81	  // overwriting the narrowed list.
82	  useEffect(() => {
83	    void loadProjects();
84	  }, [showArchived, tagFilter, statusFilter]);
85	
86	  async function onArchive(id: number) {
87	    const res = await fetch(`/api/projects/${id}/archive`, { method: 'POST' });
88	    if (res.ok) {
89	      if (openProjectId === id) {
90	        setOpenProjectId(null);
91	      }
92	      await loadProjects();
93	    }
94	  }
95	
96	  async function onDelete(id: number) {
97	    const res = await fetch(`/api/projects/${id}/delete`, { method: 'POST' });
98	    if (res.ok) {
99	      if (openProjectId === id) {
100	        setOpenProjectId(null);
101	      }
102	      await loadProjects();
103	    }
104	  }
105	
106	  async function onSubmit(event: FormEvent) {
107	    event.preventDefault();
108	    setCodeError(null);
109	    const res = await fetch('/api/projects', {
110	      method: 'POST',
111	      headers: { 'Content-Type': 'application/json' },
112	      body: JSON.stringify({ name, clientId: Number(clientId), status, code }),
113	    });
114	    if (res.ok) {
115	      // No two jobs can share a reference code: the server rejects the duplicate and adds no row.
