package net.officefloor.hq.app.clients;

import net.officefloor.web.ObjectResponse;

/** POST /api/clients — add a client from the JSON body and return the result. */
public class CreateClientLogic {

    public void service(NewClient body, ClientService clients,
            ObjectResponse<CreateClientResult> response) {
        try {
            Client saved = clients.create(body.getName(), body.getEmail());
            response.send(CreateClientResult
                    .created(new ClientView(saved.getId(), saved.getName(), saved.getEmail())));
        } catch (DuplicateClientEmailException e) {
            // Email already in use: no row added; the UI surfaces the email error.
            response.send(CreateClientResult.emailInUse());
        }
    }
}

package net.officefloor.hq.app.clients;

import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;

/** POST /api/clients/{clientId} — correct a client's name and/or email and return the result. */
public class UpdateClientLogic {

    public void service(@HttpPathParameter("clientId") String clientId, NewClient body,
            ClientService clients, ObjectResponse<UpdateClientResult> response) {
        try {
            Client saved = clients.update(Long.valueOf(clientId), body.getName(), body.getEmail());
            response.send(UpdateClientResult
                    .updated(new ClientView(saved.getId(), saved.getName(), saved.getEmail())));
        } catch (DuplicateClientEmailException e) {
            // Email already in use by another client: the row is unchanged; the UI surfaces the error.
            response.send(UpdateClientResult.emailInUse());
        }
    }
}

package net.officefloor.hq.app.clients;

import java.util.List;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;

/**
 * POST /api/clients/{clientId}/archive — tuck a client away rather than deleting it. The row is kept
 * but flagged archived so it drops off the list and the search; the action is recorded in the audit
 * log. The remaining (non-archived) clients are returned.
 */
public class ArchiveClientLogic {

    public void service(@HttpPathParameter("clientId") String clientId, ClientService clients,
            ObjectResponse<List<ClientView>> response) {
        List<ClientView> views = clients.archive(Long.valueOf(clientId)).stream()
                .map(c -> new ClientView(c.getId(), c.getName(), c.getEmail()))
                .toList();
        response.send(views);
    }
}

